    private List<CdR13FutureAssets> actual()throws Exception{if(retained!=null)return retained;String root=System.getProperty("soniccd.media.root");assumeTrue(root!=null&&!root.isBlank(),"Optional original USA media");Path cue;try(var ps=Files.list(Path.of(root).resolve("USA"))){var cues=ps.filter(p->p.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();assertEquals(1,cues.size(),"configured source must contain exactly one USA CUE");cue=cues.getFirst();}try(var p=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){retained=List.of(CdR13FutureAssets.fromPrograms(p,CdStagePayload.R13C.stage()),CdR13FutureAssets.fromPrograms(p,CdStagePayload.R13D.stage()));}return retained;}
    static byte[] hex(String s){return HexFormat.of().parseHex(s);}
    static int u16(byte[] b,int at){return(b[at]&255)<<8|(b[at+1]&255);}
    static int u32(byte[] b,int at){return u16(b,at)<<16|u16(b,at+2);}
    static String hash(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
